# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CİBRİL HADİSİ BAĞLAMINDA İMAN - İSLAM - İHSAN BÜTÜNLÜĞÜ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. İMAN (KALBÎ BOYUT)</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Kökü: Güven ve emniyet</text>\n  <text x="38" y="120" font-size="11" fill="#334155">• Özü: Kalp ile tasdik, dil ile ikrar</text>\n  <text x="38" y="142" font-size="11" fill="#334155">• Kapsamı: Altı iman esası</text>\n  <text x="48" y="158" font-size="10.5" fill="#475569">(Allah, melek, ilahi vahiy, resul,</text>\n  <text x="48" y="174" font-size="10.5" fill="#475569">ahiret, kaza ve kader)</text>\n  <text x="38" y="200" font-size="11" font-weight="bold" fill="#1d4ed8">• Kişi: Mümin</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. İSLAM (AMELÎ BOYUT)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Kökü: Barış ve teslimiyet</text>\n  <text x="260" y="120" font-size="11" fill="#334155">• Özü: İlahi emirlere itaat ve</text>\n  <text x="270" y="136" font-size="10.5" fill="#475569">ibadetleri yerine getirme</text>\n  <text x="260" y="158" font-size="11" fill="#334155">• Kapsamı: Kelime-i şehadet,</text>\n  <text x="270" y="174" font-size="10.5" fill="#475569">namaz, oruç, zekât ve hac</text>\n  <text x="260" y="200" font-size="11" font-weight="bold" fill="#15803d">• Kişi: Müslüman</text>\n  <rect x="469" y="48" width="205" height="190" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="571" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">3. İHSAN (AHLAKİ ZİRVE)</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• Kökü: İyilik ve güzellik</text>\n  <text x="482" y="120" font-size="11" fill="#334155">• Özü: Allah\'ı görüyormuşçasına</text>\n  <text x="492" y="136" font-size="10.5" fill="#475569">bilinçli ve özenli kulluk</text>\n  <text x="482" y="158" font-size="10.5" font-weight="bold" fill="#a16207">&quot;Sen O\'nu görmesen de O seni</text>\n  <text x="482" y="174" font-size="10.5" font-weight="bold" fill="#a16207">görmektedir.&quot; (Hadis-i Şerif)</text>\n  <text x="482" y="200" font-size="11" font-weight="bold" fill="#854d0e">• Kişi: Muhsin</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANI BESLEYEN VE KORUYAN DÖRT TEMEL BİLİNÇ KAVRAMI</text>\n  <rect x="25" y="48" width="315" height="90" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">İHLAS (SAMİMİYET) — MUHLİS</text>\n  <text x="40" y="92" font-size="11" fill="#334155">• İbadetleri gösterişten (riyadan) arındırarak</text>\n  <text x="50" y="108" font-size="11" fill="#334155">katıksızca Allah rızası için yapma bilinci.</text>\n  <text x="40" y="126" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Zıddı: Riya (Gösteriş ve çıkar beklentisi)</text>\n  <rect x="360" y="48" width="315" height="90" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TAKVA (SORUMLULUK) — MÜTTAKİ</text>\n  <text x="375" y="92" font-size="11" fill="#334155">• Allah\'a saygıdan dolayı emirlere sarılıp</text>\n  <text x="385" y="108" font-size="11" fill="#334155">günahlardan ve haramlardan korunma bilinci.</text>\n  <text x="375" y="126" font-size="10.5" font-weight="bold" fill="#15803d">• Ölçü: Allah katında üstünlüğün temel kriteri</text>\n  <rect x="25" y="152" width="315" height="90" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">HİDAYET (REHBERLİK) — MÜHTEDİ</text>\n  <text x="40" y="196" font-size="11" fill="#334155">• Allah\'ın vahiy ve akıl yoluyla doğru yolu</text>\n  <text x="50" y="212" font-size="11" fill="#334155">göstermesi, insanın da iradesiyle hakka yönelmesi.</text>\n  <text x="40" y="230" font-size="10.5" font-weight="bold" fill="#a16207">• Zıddı: Dalalet (Doğru yoldan sapma / şaşırma)</text>\n  <rect x="360" y="152" width="315" height="90" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">SIRAT-I MÜSTAKİM (DOĞRU YOL)</text>\n  <text x="375" y="196" font-size="11" fill="#334155">• İfrat ve tefritten (aşırılıklardan) uzak,</text>\n  <text x="385" y="212" font-size="11" fill="#334155">tevhid ve ahlak üzere kurulu dosdoğru İslam yolu.</text>\n  <text x="375" y="230" font-size="10.5" font-weight="bold" fill="#7e22ce">• Dua: Fâtiha suresinin merkezî niyazı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMAN VE TEVHİDİN ZIDDI OLAN TUTUMLARIN KARŞILAŞTIRILMASI</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">1. KÜFÜR (KÂFİR)</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Kök Anlamı: Hakikati örtmek,</text>\n  <text x="48" y="114" font-size="10.5" fill="#475569">gizlemek ve nankörlük etmek</text>\n  <text x="38" y="138" font-size="11" fill="#334155">• Terim Anlamı: İman esaslarının</text>\n  <text x="48" y="154" font-size="10.5" fill="#475569">tamamını veya bir kısmını</text>\n  <text x="48" y="170" font-size="10.5" fill="#475569">kalben ve dilen inkâr etmek</text>\n  <text x="38" y="198" font-size="11" font-weight="bold" fill="#b91c1c">• Zıddı: İman (Tasdik)</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">2. ŞİRK (MÜŞRİK)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Kök Anlamı: Ortak koşmak</text>\n  <text x="260" y="122" font-size="11" fill="#334155">• Terim Anlamı: Allah\'ın zatında,</text>\n  <text x="270" y="138" font-size="10.5" fill="#475569">sıfatlarında veya ibadette</text>\n  <text x="270" y="154" font-size="10.5" fill="#475569">başka varlıkları O\'na denk</text>\n  <text x="270" y="170" font-size="10.5" fill="#475569">ve ortak kabul etmek</text>\n  <text x="260" y="198" font-size="11" font-weight="bold" fill="#c2410c">• Zıddı: Tevhid (Birleme)</text>\n  <rect x="469" y="48" width="205" height="190" rx="10" fill="#f1f5f9" stroke="#475569" stroke-width="2"/>\n  <text x="571" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e293b">3. NİFAK (MÜNAFIK)</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• Kök Anlamı: İkiyüzlülük</text>\n  <text x="482" y="122" font-size="11" fill="#334155">• Terim Anlamı: Kalbiyle</text>\n  <text x="492" y="138" font-size="10.5" fill="#475569">inanmadığı (inkâr ettiği) hâlde</text>\n  <text x="492" y="154" font-size="10.5" fill="#475569">çıkar için diliyle mümin</text>\n  <text x="492" y="170" font-size="10.5" fill="#475569">görünerek aldatmak</text>\n  <text x="482" y="198" font-size="11" font-weight="bold" fill="#334155">• Zıddı: Sıdk ve İhlas</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
